/**
 * 定位授权与地点信息获取。
 * - H5：优先 navigator.geolocation；若只是权限问题（PERMISSION_DENIED），走浏览器原生权限弹窗/系统设置重新申请。
 * - 小程序：uni.getLocation + 授权设置（uni.openSetting）重新获取权限。
 * 统一返回可读的地点文案；失败抛出中文错误，便于页面直接 toast。
 */
export interface GeoPlace {
  address: string
  latitude: number
  longitude: number
  time: number
}

export class GeoError extends Error {
  denied: boolean
  constructor(message: string, denied = false) {
    super(message)
    this.denied = denied
  }
}

/** 格式化时间：YYYY-MM-DD HH:mm:ss */
export function formatTime(ts: number): string {
  const d = new Date(ts)
  const p = (n: number) => String(n).padStart(2, '0')
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}:${p(d.getSeconds())}`
}

/** 获取当前位置并返回地点文案。notFoundText 用于反地理编码失败时仍能给出「纬度,经度」。 */
export async function getCurrentPlace(): Promise<GeoPlace> {
  // #ifdef H5
  return getPlaceH5()
  // #endif
  // #ifndef H5
  return getPlaceMP()
  // #endif
}

// #ifdef H5
function getPlaceH5(): Promise<GeoPlace> {
  return new Promise((resolve, reject) => {
    if (!navigator.geolocation) { reject(new GeoError('当前浏览器不支持定位', true)); return }
    navigator.geolocation.getCurrentPosition(
      async pos => {
        const { latitude, longitude } = pos.coords
        const time = pos.timestamp || Date.now()
        let address = ''
        try { address = await reverseGeocodeH5(latitude, longitude) } catch { /* 反地理编码失败不阻断拍照 */ }
        resolve({ address: address || `${latitude.toFixed(6)},${longitude.toFixed(6)}`, latitude, longitude, time })
      },
      err => {
        const denied = err.code === err.PERMISSION_DENIED
        const msg = denied ? '未获取到定位权限，请允许定位后重新获取位置' : err.code === err.TIMEOUT ? '定位超时，请重新获取位置' : '无法获取当前位置，请重新获取位置'
        reject(new GeoError(msg, denied))
      },
      { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 },
    )
  })
}

/** 浏览器端反地理编码：优先用高德/腾讯等已配置 key，缺失时退回经纬度文案。 */
async function reverseGeocodeH5(lat: number, lng: number): Promise<string> {
  const env = import.meta.env as Record<string, string | undefined>
  const amapKey = env.VITE_AMAP_KEY
  if (!amapKey) return ''
  try {
    const resp = await fetch(`https://restapi.amap.com/v3/geocode/regeo?key=${encodeURIComponent(amapKey)}&location=${lng.toFixed(6)},${lat.toFixed(6)}`)
    const body: any = await resp.json()
    const addr = body?.regeocode?.formatted_address
    return typeof addr === 'string' && addr ? addr : ''
  } catch { return '' }
}
// #endif

// #ifndef H5
function getPlaceMP(): Promise<GeoPlace> {
  return new Promise((resolve, reject) => {
    uni.getLocation({
      type: 'gcj02',
      isHighAccuracy: true,
      success: async res => {
        const latitude = Number(res.latitude)
        const longitude = Number(res.longitude)
        let address = ''
        try { address = await reverseGeocodeMP(latitude, longitude) } catch { /* 忽略 */ }
        resolve({ address: address || `${latitude.toFixed(6)},${longitude.toFixed(6)}`, latitude, longitude, time: Date.now() })
      },
      fail: err => {
        const msg = String(err?.errMsg || '')
        if (/auth|deny|denied|authorize/i.test(msg)) reject(new GeoError('未获取到定位权限，请允许定位后重新获取位置', true))
        else reject(new GeoError('无法获取当前位置，请重新获取位置'))
      },
    })
  })
}

function reverseGeocodeMP(lat: number, lng: number): Promise<string> {
  return new Promise(resolve => {
    // 小程序端可用地图选点/逆地址解析插件，未接入时退回经纬度
    resolve(`${lat.toFixed(6)},${lng.toFixed(6)}`)
  })
}
// #endif

/**
 * 重新获取定位权限（用户此前拒绝过授权时）。
 * - H5：无法直接编程重新申请，只能提示用户在浏览器/系统设置中开启定位；返回定位结果以便再次尝试。
 * - 小程序：调用 uni.openSetting 引导开启。
 */
export async function reacquireLocationPermission(): Promise<void> {
  // #ifdef H5
  // 浏览器无单独授权 API，直接再次请求定位会触发浏览器权限弹窗（若用户已永久拒绝则需到设置里开启）
  return getPlaceH5().then(() => undefined)
  // #endif
  // #ifndef H5
  await new Promise<void>(resolve => {
    uni.getSetting({
      success: res => {
        if (res.authSetting && res.authSetting['scope.userLocation']) { resolve(); return }
        uni.openSetting({ complete: () => resolve() })
      },
      fail: () => resolve(),
    })
  })
  // #endif
}

import { formatTime } from './geo'

/**
 * 给图片右下角叠加水印（时间 + 地点）。
 * - H5：用 canvas 绘制原图 + 半透明水印条，导出为 jpeg blob URL。
 * - 非 H5（小程序）：用离屏 canvas 绘制后 canvasToTempFilePath 导出临时文件。
 * 水印内容包含「时间、地点等关键信息」，满足不可随便选手机相册、须含水印的要求。
 */
export interface WatermarkInfo {
  address: string
  time: number
}

// #ifdef H5
export async function applyWatermark(src: string, info: WatermarkInfo): Promise<string> {
  const img = await loadImage(src)
  const maxW = 1280
  const scale = Math.min(1, maxW / img.naturalWidth)
  const w = Math.max(1, Math.round(img.naturalWidth * scale))
  const h = Math.max(1, Math.round(img.naturalHeight * scale))
  const canvas = document.createElement('canvas')
  canvas.width = w
  canvas.height = h
  const ctx = canvas.getContext('2d')
  if (!ctx) return src
  ctx.drawImage(img, 0, 0, w, h)
  paintWatermark(ctx, w, h, info)
  const blob = await new Promise<Blob | null>(resolve => canvas.toBlob(resolve, 'image/jpeg', 0.9))
  if (!blob) return src
  return URL.createObjectURL(blob)
}

function loadImage(src: string): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    const img = new Image()
    img.onload = () => resolve(img)
    img.onerror = () => reject(new Error('图片加载失败'))
    img.src = src
  })
}

function paintWatermark(ctx: CanvasRenderingContext2D, w: number, h: number, info: WatermarkInfo) {
  const lines = [`时间：${formatTime(info.time)}`, `地点：${info.address}`]
  const pad = Math.round(Math.min(w, h) * 0.03)
  const fontSize = Math.max(14, Math.round(w * 0.028))
  ctx.font = `${fontSize}px -apple-system, "PingFang SC", sans-serif`
  ctx.textBaseline = 'bottom'
  const lineH = Math.round(fontSize * 1.4)
  const blockH = lineH * lines.length + pad
  // 底部半透明背景条，保证水印清晰可读
  ctx.fillStyle = 'rgba(0,0,0,0.42)'
  ctx.fillRect(0, h - blockH, w, blockH)
  ctx.fillStyle = '#ffffff'
  lines.forEach((line, i) => {
    ctx.fillText(line, pad, h - pad - (lines.length - 1 - i) * lineH)
  })
}
// #endif

// #ifndef H5
export function applyWatermark(src: string, info: WatermarkInfo): Promise<string> {
  return new Promise((resolve, reject) => {
    uni.getImageInfo({
      src,
      success: infoRes => {
        const W = Math.min(1280, infoRes.width)
        const ratio = W / infoRes.width
        const H = Math.round(infoRes.height * ratio)
        const canvasId = `wm-${Date.now()}-${Math.random().toString(36).slice(2)}`
        const ctx = uni.createCanvasContext(canvasId)
        ctx.drawImage(infoRes.path, 0, 0, W, H)
        const lines = [`时间：${formatTime(info.time)}`, `地点：${info.address}`]
        const pad = Math.round(Math.min(W, H) * 0.03)
        const fontSize = Math.max(14, Math.round(W * 0.028))
        const lineH = Math.round(fontSize * 1.4)
        const blockH = lineH * lines.length + pad
        ctx.setFillStyle('rgba(0,0,0,0.42)')
        ctx.fillRect(0, H - blockH, W, blockH)
        ctx.setFillStyle('#ffffff')
        ctx.setFontSize(fontSize)
        lines.forEach((line, i) => ctx.fillText(line, pad, H - pad - (lines.length - 1 - i) * lineH))
        ctx.draw(false, () => {
          uni.canvasToTempFilePath({
            canvasId,
            success: res => resolve(res.tempFilePath),
            fail: () => reject(new Error('水印生成失败')),
          })
        })
      },
      fail: () => reject(new Error('图片读取失败')),
    })
  })
}
// #endif

